dashboard.definition:
{
	"title": "DLP and Cloud Native Security",
	"description": "Hybrid Mesh Firewalling drill-down dashboard for DLP and Cloud Native Security.",
	"inputs": {
		"input_time_range": {
			"options": {
				"defaultValue": "-24h@h,now",
				"token": "time_tok"
			},
			"title": "Time Range",
			"type": "input.timerange"
		}
	},
	"defaults": {
		"visualizations": {
			"global": {
				"showLastUpdated": true,
				"showProgressBar": true
			}
		}
	},
	"visualizations": {
		"viz_header_bg": {
			"type": "splunk.rectangle",
			"options": {
				"fillColor": "#0f172a",
				"strokeColor": "rgba(148,163,184,0.22)"
			}
		},
		"viz_header_icon": {
			"type": "splunk.image",
			"title": "Hybrid Mesh Firewalling",
			"options": {
				"preserveAspectRatio": true,
				"src": "/static/app/splunk-cisco-dashboards/images/overview/secure-networking/hybrid-mesh-firewalling.svg"
			}
		},
		"viz_header": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "transparent",
				"fontColor": "#e2e8f0",
				"markdown": "# DLP and Cloud Native Security\nHybrid Mesh Firewalling • Searchbase-backed operational views."
			}
		},
		"viz_secure_networking_secure_access_dlp_findings": {
			"type": "splunk.table",
			"title": "Secure Access DLP Findings",
			"dataSources": {
				"primary": "ds_secure_networking_secure_access_dlp_findings"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			}
		},
		"viz_secure_networking_segmentation_secure_workload_alerts_by_type": {
			"type": "splunk.table",
			"title": "Segmentation Secure Workload Alerts by Type",
			"dataSources": {
				"primary": "ds_secure_networking_segmentation_secure_workload_alerts_by_type"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			}
		},
		"viz_security_microseg_tetration_alerts_by_severity_type": {
			"type": "splunk.bar",
			"title": "Secure Workload Alerts by Severity and Type",
			"dataSources": {
				"primary": "ds_security_microseg_tetration_alerts_by_severity_type"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"legendDisplay": "bottom",
				"seriesColors": [
					"#DC2626",
					"#F59E0B",
					"#2563EB",
					"#16A34A"
				],
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"stackMode": "unstacked"
			}
		},
		"viz_secure_networking_cloud_native_security_activity": {
			"type": "splunk.bar",
			"title": "Cloud Native Security Activity by Provider",
			"dataSources": {
				"primary": "ds_secure_networking_cloud_native_security_activity"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"legendDisplay": "bottom",
				"seriesColors": [
					"#F59E0B",
					"#2563EB",
					"#16A34A"
				],
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"stackMode": "stacked"
			}
		}
	},
	"dataSources": {
		"ds_secure_networking_secure_access_dlp_findings": {
			"name": "Secure Networking - Secure Access DLP Findings",
			"options": {
				"ref": "secure_networking_secure_access_dlp_findings",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_secure_networking_segmentation_secure_workload_alerts_by_type": {
			"name": "Secure Networking - Segmentation Secure Workload Alerts by Type",
			"options": {
				"ref": "secure_networking_segmentation_secure_workload_alerts_by_type",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_security_microseg_tetration_alerts_by_severity_type": {
			"name": "Security - Microsegmentation - Secure Workload Alerts by Severity and Type",
			"options": {
				"ref": "security_microseg_tetration_alerts_by_severity_type",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_secure_networking_cloud_native_security_activity": {
			"name": "Secure Networking - Cloud Native Security Activity by Provider",
			"options": {
				"ref": "secure_networking_cloud_native_security_activity",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		}
	},
	"layout": {
		"globalInputs": [
			"input_time_range"
		],
		"layoutDefinitions": {
			"layout_overview": {
				"options": {
					"backgroundColor": "#020617",
					"display": "auto-scale",
					"height": 890,
					"width": 1440
				},
				"structure": [
					{
						"item": "viz_header_bg",
						"position": {
							"x": 20,
							"y": 0,
							"w": 1400,
							"h": 90
						},
						"type": "block"
					},
					{
						"item": "viz_header_icon",
						"position": {
							"x": 36,
							"y": 9,
							"w": 72,
							"h": 72
						},
						"type": "block"
					},
					{
						"item": "viz_header",
						"position": {
							"x": 120,
							"y": 0,
							"w": 1300,
							"h": 90
						},
						"type": "block"
					},
					{
						"item": "viz_secure_networking_secure_access_dlp_findings",
						"position": {
							"x": 20,
							"y": 110,
							"w": 690,
							"h": 360
						},
						"type": "block"
					},
					{
						"item": "viz_secure_networking_segmentation_secure_workload_alerts_by_type",
						"position": {
							"x": 730,
							"y": 110,
							"w": 690,
							"h": 360
						},
						"type": "block"
					},
					{
						"item": "viz_security_microseg_tetration_alerts_by_severity_type",
						"position": {
							"x": 20,
							"y": 490,
							"w": 690,
							"h": 360
						},
						"type": "block"
					},
					{
						"item": "viz_secure_networking_cloud_native_security_activity",
						"position": {
							"x": 730,
							"y": 490,
							"w": 690,
							"h": 360
						},
						"type": "block"
					}
				],
				"type": "absolute"
			}
		},
		"options": {
			"showTitleAndDescription": false,
			"submitButton": false,
			"submitOnDashboardLoad": true
		},
		"tabs": {
			"items": [
				{
					"label": "overview",
					"layoutId": "layout_overview"
				}
			]
		}
	},
	"applicationProperties": {
		"collapseNavigation": false,
		"hideEdit": false,
		"hideExport": false
	}
}
